/**
 * Automation audit 2026-11-08: the connection of the online partition runner
 * (role `lawbid_partition`, owner of the tables it converts).
 *
 * 1. `PARTITION_DATABASE_URL` when set (old hand-filled secret, local dev).
 * 2. Otherwise `DATABASE_URL` with the login swapped for `lawbid_partition`
 *    and `PARTITION_DB_PASSWORD` (generated by Terraform when
 *    `partition_role_enabled = true`, set on the role by the migrate task:
 *    prisma/ensure-partition-login.mjs). Same host, port, database and
 *    options as the app, so nothing else has to be configured by hand.
 *
 * Returns undefined when neither is available (the card stays read-only).
 */
export const PARTITION_LOGIN = 'lawbid_partition';

export function partitionDatabaseUrl(
  get: (name: string) => string | undefined,
): string | undefined {
  const direct = get('PARTITION_DATABASE_URL')?.trim();
  if (direct) return direct;
  const password = get('PARTITION_DB_PASSWORD')?.trim();
  const base = get('DATABASE_URL')?.trim();
  if (!password || !base) return undefined;
  let u: URL;
  try {
    u = new URL(base);
  } catch {
    return undefined;
  }
  if (!/^postgres(ql)?:$/.test(u.protocol)) return undefined;
  u.username = PARTITION_LOGIN;
  u.password = password;
  // A pooler in transaction mode would break the runner's session-level
  // work (advisory locks, SET); the app URL is direct today. Prisma's own
  // pool size for the runner stays tiny.
  if (!u.searchParams.has('connection_limit')) {
    u.searchParams.set('connection_limit', '2');
  }
  return u.toString();
}
